def predire(x, w, b):
    return w * x + b

exemples = [(1, 3), (2, 5), (3, 7)]
for x, cible in exemples:
    print(x, predire(x, 2, 1), cible)

def relu(x):
    return max(0, x)

print(relu(-2), relu(0), relu(3))

def sgd(parameter, gradient, learning_rate):
    return parameter - learning_rate * gradient

print(sgd(1.0, 0.5, 0.1))

