def empiler(x, blocs):
    for bloc in blocs:
        x = bloc(x)
    return x

def pas_internes(etat, k):
    for _ in range(k):
        etat = etat * 0.5 + 1.0
    return etat
print(pas_internes(0.0, 1), pas_internes(0.0, 4))

